CREATE SCHEMA mina;;
CREATE SEQUENCE mina.primary_key_gen_seq INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START 5 NO CYCLE;;
CREATE TYPE mina.account_type AS ENUM ( 'OWNED', 'PARTY', 'FLOW', 'SYSTEM' );;;
CREATE TYPE mina.category_economic_intent AS ENUM ( 'EXPENSE', 'INCOME' );;;
CREATE TYPE mina.reconciliation_status AS ENUM ( 'RECONCILED', 'UNRECONCILED' );;;
CREATE TYPE mina.record_link_type AS ENUM ( 'REFUND', 'REIMBURSEMENT' );;;
CREATE TYPE mina.recurring_occurrence_status AS ENUM ( 'EXPECTED', 'CONFIRMED', 'DISMISSED', 'DEFERRED' );;;
CREATE TYPE mina."source" AS ENUM ( 'MANUAL', 'IMPORTED', 'RECURRING_TEMPLATE' );;;
CREATE TYPE mina.transaction_lifecycle_status AS ENUM ( 'ACTIVE', 'EXPECTED', 'CANCELLED' );;;
CREATE TABLE mina.account(account_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, fqn VARCHAR NOT NULL, display_label VARCHAR, account_type ENUM('OWNED', 'PARTY', 'FLOW', 'SYSTEM') NOT NULL, is_hidden BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, is_featured BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, currency VARCHAR, external_id VARCHAR, external_system VARCHAR, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP, parent_fqn VARCHAR GENERATED ALWAYS AS(CASE  WHEN ((instr(fqn, ':') > 0)) THEN (regexp_replace(fqn, ':[^:]+$', '')) ELSE NULL END), "name" VARCHAR GENERATED ALWAYS AS(regexp_extract(fqn, '[^:]+$')), "level" INTEGER GENERATED ALWAYS AS((array_length(string_split(fqn, ':')) - 1)), UNIQUE(fqn, tombstoned_at));;
CREATE TABLE mina.budget(budget_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, category_fqn VARCHAR NOT NULL, "month" DATE NOT NULL, amount DECIMAL(18,8) NOT NULL, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP, UNIQUE(category_fqn, "month", tombstoned_at));;
CREATE TABLE mina.category(category_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, fqn VARCHAR NOT NULL, economic_intent ENUM('EXPENSE', 'INCOME') NOT NULL, is_hidden BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, is_featured BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP, parent_fqn VARCHAR GENERATED ALWAYS AS(CASE  WHEN ((instr(fqn, ':') > 0)) THEN (regexp_replace(fqn, ':[^:]+$', '')) ELSE NULL END), "name" VARCHAR GENERATED ALWAYS AS(regexp_extract(fqn, '[^:]+$')), "level" INTEGER GENERATED ALWAYS AS((array_length(string_split(fqn, ':')) - 1)), UNIQUE(fqn, tombstoned_at));;
CREATE TABLE mina.credit_limit_history(credit_limit_history_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, account_id INTEGER NOT NULL, credit_limit DECIMAL(18,8) NOT NULL, effective_date DATE NOT NULL, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP, UNIQUE(account_id, effective_date, tombstoned_at));;
CREATE TABLE mina.exchange_rate(exchange_rate_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, from_currency VARCHAR NOT NULL, to_currency VARCHAR NOT NULL, rate DECIMAL(18,8) NOT NULL, effective_date TIMESTAMP NOT NULL, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP, UNIQUE(from_currency, to_currency, effective_date, tombstoned_at));;
CREATE TABLE mina.imported_record_metadata(imported_record_metadata_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, record_id INTEGER NOT NULL, external_system VARCHAR NOT NULL, external_id VARCHAR, description VARCHAR, merchant_name VARCHAR, mcc_code VARCHAR, provider_category VARCHAR, provider_category_detailed VARCHAR, provider_status VARCHAR, provider_authorized_at TIMESTAMP, provider_posted_at TIMESTAMP, raw_payload JSON, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP, UNIQUE(record_id, tombstoned_at));;
CREATE TABLE mina.journal_record(record_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, transaction_id INTEGER NOT NULL, account_id INTEGER NOT NULL, member_id INTEGER, currency VARCHAR NOT NULL, amount DECIMAL(18,8) NOT NULL, amount_usd DECIMAL(18,8), category_id INTEGER, tag_ids INTEGER[] DEFAULT(main.list_value()) NOT NULL, memo VARCHAR, pending_date TIMESTAMP, posted_date TIMESTAMP DEFAULT(NULL), reconciliation_status ENUM('RECONCILED', 'UNRECONCILED') DEFAULT('RECONCILED') NOT NULL, "source" ENUM('MANUAL', 'IMPORTED', 'RECURRING_TEMPLATE') NOT NULL, external_id VARCHAR, external_system VARCHAR, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP);;
CREATE TABLE mina.member(member_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, "name" VARCHAR NOT NULL, is_hidden BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP, UNIQUE("name", tombstoned_at));;
CREATE TABLE mina.record_link(record_link_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, origin_record_id INTEGER NOT NULL, settlement_record_id INTEGER NOT NULL, link_type ENUM('REFUND', 'REIMBURSEMENT') NOT NULL, memo VARCHAR, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP, UNIQUE(origin_record_id, settlement_record_id, tombstoned_at));;
CREATE TABLE mina.recurring_definition(recurring_definition_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, fqn VARCHAR NOT NULL, schedule_rule JSON NOT NULL, anchor_date DATE NOT NULL, definition_version INTEGER DEFAULT(1) NOT NULL, paused_at TIMESTAMP, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP, parent_fqn VARCHAR GENERATED ALWAYS AS(CASE  WHEN ((instr(fqn, ':') > 0)) THEN (regexp_replace(fqn, ':[^:]+$', '')) ELSE NULL END), "name" VARCHAR GENERATED ALWAYS AS(regexp_extract(fqn, '[^:]+$')), "level" INTEGER GENERATED ALWAYS AS((array_length(split(fqn, ':')) - 1)), UNIQUE(fqn, tombstoned_at));;
CREATE TABLE mina.recurring_definition_record(recurring_definition_record_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, recurring_definition_id INTEGER NOT NULL, account_id INTEGER NOT NULL, member_id INTEGER, currency VARCHAR NOT NULL, amount DECIMAL(18,8) NOT NULL, category_id INTEGER, tag_ids INTEGER[] DEFAULT(main.list_value()) NOT NULL, memo VARCHAR, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP);;
CREATE TABLE mina.recurring_occurrence(recurring_occurrence_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, recurring_definition_id INTEGER NOT NULL, scheduled_date DATE NOT NULL, status ENUM('EXPECTED', 'CONFIRMED', 'DISMISSED', 'DEFERRED') DEFAULT('EXPECTED') NOT NULL, materialized_definition_version INTEGER NOT NULL, materialized_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, reviewed_at TIMESTAMP, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, UNIQUE(recurring_definition_id, scheduled_date));;
CREATE TABLE mina.schema_version(id INTEGER PRIMARY KEY, version_id BIGINT NOT NULL, is_applied BOOLEAN NOT NULL, tstamp TIMESTAMP DEFAULT(now()) NOT NULL);;
CREATE TABLE mina.tag(tag_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, fqn VARCHAR NOT NULL, is_hidden BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, is_featured BOOLEAN DEFAULT(CAST('f' AS BOOLEAN)) NOT NULL, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP, parent_fqn VARCHAR GENERATED ALWAYS AS(CASE  WHEN ((instr(fqn, ':') > 0)) THEN (regexp_replace(fqn, ':[^:]+$', '')) ELSE NULL END), "name" VARCHAR GENERATED ALWAYS AS(regexp_extract(fqn, '[^:]+$')), "level" INTEGER GENERATED ALWAYS AS((array_length(string_split(fqn, ':')) - 1)), UNIQUE(fqn, tombstoned_at));;
CREATE TABLE mina."transaction"(transaction_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, initiated_date DATE NOT NULL, recurring_occurrence_id INTEGER, lifecycle_status ENUM('ACTIVE', 'EXPECTED', 'CANCELLED') NOT NULL, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP);;
CREATE TABLE mina.transaction_template(transaction_template_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, fqn VARCHAR NOT NULL, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP, parent_fqn VARCHAR GENERATED ALWAYS AS(CASE  WHEN ((instr(fqn, ':') > 0)) THEN (regexp_replace(fqn, ':[^:]+$', '')) ELSE NULL END), "name" VARCHAR GENERATED ALWAYS AS(regexp_extract(fqn, '[^:]+$')), "level" INTEGER GENERATED ALWAYS AS((array_length(string_split(fqn, ':')) - 1)), UNIQUE(fqn, tombstoned_at));;
CREATE TABLE mina.transaction_template_record(transaction_template_record_id INTEGER DEFAULT(nextval('primary_key_gen_seq')) PRIMARY KEY, transaction_template_id INTEGER NOT NULL, category_id INTEGER, account_id INTEGER, member_id INTEGER, currency VARCHAR, amount DECIMAL(18,8), tag_ids INTEGER[] DEFAULT(main.list_value()) NOT NULL, memo VARCHAR, created_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, updated_at TIMESTAMP DEFAULT(CURRENT_TIMESTAMP) NOT NULL, tombstoned_at TIMESTAMP);;
CREATE UNIQUE INDEX account_active_fqn_unique ON mina.account((CASE  WHEN ((tombstoned_at IS NULL)) THEN (fqn) ELSE NULL END));;
CREATE UNIQUE INDEX budget_active_category_month_unique ON mina.budget((CASE  WHEN ((tombstoned_at IS NULL)) THEN (((category_fqn || ':') || CAST("month" AS VARCHAR))) ELSE NULL END));;
CREATE UNIQUE INDEX category_active_fqn_unique ON mina.category((CASE  WHEN ((tombstoned_at IS NULL)) THEN (fqn) ELSE NULL END));;
CREATE UNIQUE INDEX credit_limit_history_active_account_date_unique ON mina.credit_limit_history((CASE  WHEN ((tombstoned_at IS NULL)) THEN (((CAST(account_id AS VARCHAR) || ':') || CAST(effective_date AS VARCHAR))) ELSE NULL END));;
CREATE UNIQUE INDEX exchange_rate_active_pair_date_unique ON mina.exchange_rate((CASE  WHEN ((tombstoned_at IS NULL)) THEN (((((from_currency || ':') || to_currency) || ':') || CAST(effective_date AS VARCHAR))) ELSE NULL END));;
CREATE UNIQUE INDEX imported_record_metadata_active_record_unique ON mina.imported_record_metadata((CASE  WHEN ((tombstoned_at IS NULL)) THEN (record_id) ELSE NULL END));;
CREATE INDEX journal_record_transaction_id_idx ON mina.journal_record(transaction_id);;
CREATE UNIQUE INDEX member_active_name_unique ON mina.member((CASE  WHEN ((tombstoned_at IS NULL)) THEN ("name") ELSE NULL END));;
CREATE UNIQUE INDEX record_link_active_pair_unique ON mina.record_link((CASE  WHEN ((tombstoned_at IS NULL)) THEN (((CAST(origin_record_id AS VARCHAR) || ':') || CAST(settlement_record_id AS VARCHAR))) ELSE NULL END));;
CREATE UNIQUE INDEX recurring_definition_active_fqn_unique ON mina.recurring_definition((CASE  WHEN ((tombstoned_at IS NULL)) THEN (fqn) ELSE NULL END));;
CREATE UNIQUE INDEX tag_active_fqn_unique ON mina.tag((CASE  WHEN ((tombstoned_at IS NULL)) THEN (fqn) ELSE NULL END));;
CREATE UNIQUE INDEX transaction_template_active_fqn_unique ON mina.transaction_template((CASE  WHEN ((tombstoned_at IS NULL)) THEN (fqn) ELSE NULL END));;
